// US-APP-14 · Secrets are hidden and can be revealed by an admin: a secret shows a "secret" badge and a masked value
// (never sent until revealed); the reveal button fetches it and shows it until hidden; a generated secret can be
// revealed and copied but not edited ("Generated by hlabs"); a variable someone adds can be marked secret; hidden
// settings show only after "Show advanced".
import { fireEvent, screen, waitFor, within } from '@testing-library/react';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { currentToasts, dismissToast } from '../lib/toasts';
import { renderConfig } from '../test/app-config';

afterEach(() => {
  for (const t of currentToasts()) dismissToast(t.id);
  vi.restoreAllMocks();
});

const envList = () => screen.findByRole('group', { name: 'Environment variables' });
const showAdvanced = () => fireEvent.click(screen.getByRole('button', { name: 'Show advanced' }));

describe('US-APP-14', () => {
  it('a secret shows a "secret" badge and a masked value', async () => {
    const { container } = renderConfig();
    await envList();
    const field = screen.getByLabelText('Value of SMTP_PASSWORD');
    expect(field).toHaveAttribute('type', 'password');
    expect(field).toHaveValue('');
    expect(field).toHaveAttribute('placeholder', '••••••••');
    expect(screen.getAllByText('secret').length).toBeGreaterThan(0);
    // Nothing secret is on the page.
    expect(container.innerHTML).not.toContain('mail-pass');
  });

  it('the reveal button fetches the value and shows it until hidden', async () => {
    const { calls } = renderConfig({ 'apps.revealSecret': () => ({ value: 'mail-pass' }) });
    await envList();
    fireEvent.click(screen.getByRole('button', { name: 'Show SMTP_PASSWORD' }));
    const field = screen.getByLabelText('Value of SMTP_PASSWORD');
    await waitFor(() => expect(field).toHaveValue('mail-pass'));
    expect(field).toHaveAttribute('type', 'text');
    expect(calls.find((c) => c.path === 'apps.revealSecret')?.input).toEqual({
      appId: 'vaultwarden',
      key: 'SMTP_PASSWORD',
    });
    // Revealing isn't a change to save.
    expect(screen.getByRole('button', { name: 'Save and restart app' })).toBeDisabled();
    fireEvent.click(screen.getByRole('button', { name: 'Hide SMTP_PASSWORD' }));
    expect(field).toHaveAttribute('type', 'password');
    expect(field).toHaveValue('');
  });

  it('hidden settings appear only after "Show advanced"', async () => {
    renderConfig();
    await envList();
    expect(screen.queryByLabelText('Value of ADMIN_TOKEN')).toBeNull();
    showAdvanced();
    expect(screen.getByLabelText('Value of ADMIN_TOKEN')).toBeInTheDocument();
    fireEvent.click(screen.getByRole('button', { name: 'Hide advanced' }));
    expect(screen.queryByLabelText('Value of ADMIN_TOKEN')).toBeNull();
  });

  it('a generated secret is read only, says "Generated by hlabs", and can be revealed and copied', async () => {
    const writeText = vi.fn(() => Promise.resolve());
    Object.assign(navigator, { clipboard: { writeText } });
    renderConfig({ 'apps.revealSecret': () => ({ value: 'generated-token' }) });
    await envList();
    showAdvanced();
    const field = screen.getByLabelText('Value of ADMIN_TOKEN');
    expect(field).toHaveAttribute('readonly');
    expect(screen.getByText('Generated by hlabs')).toBeInTheDocument();
    fireEvent.click(screen.getByRole('button', { name: 'Copy ADMIN_TOKEN' }));
    await waitFor(() => expect(writeText).toHaveBeenCalledWith('generated-token'));
    expect(field).toHaveValue('generated-token');
    expect(currentToasts()).toContainEqual(expect.objectContaining({ title: 'ADMIN_TOKEN copied' }));
  });

  it('a variable someone adds can be marked secret before saving', async () => {
    const { calls } = renderConfig({ 'apps.setConfig': () => ({ jobId: 'j1' }) });
    await envList();
    fireEvent.click(screen.getByRole('button', { name: '+ Add variable' }));
    fireEvent.change(screen.getByRole('textbox', { name: 'Name of the new variable' }), {
      target: { value: 'API_KEY' },
    });
    fireEvent.click(screen.getByRole('switch', { name: 'Keep API_KEY secret' }));
    const value = screen.getByLabelText('Value of API_KEY');
    expect(value).toHaveAttribute('type', 'password');
    fireEvent.change(value, { target: { value: 'k-123' } });
    fireEvent.click(screen.getByRole('button', { name: 'Save and restart app' }));
    await waitFor(() => expect(calls.find((c) => c.path === 'apps.setConfig')).toBeDefined());
    const env = (calls.find((c) => c.path === 'apps.setConfig')!.input as { env: unknown[] }).env;
    expect(env).toContainEqual({ key: 'API_KEY', value: 'k-123', secret: true });
  });

  it('a new secret needs a value', async () => {
    renderConfig();
    const list = await envList();
    fireEvent.click(within(list).getByRole('button', { name: '+ Add variable' }));
    fireEvent.change(screen.getByRole('textbox', { name: 'Name of the new variable' }), {
      target: { value: 'API_KEY' },
    });
    fireEvent.click(screen.getByRole('switch', { name: 'Keep API_KEY secret' }));
    expect(await screen.findByText('Enter a value')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Save and restart app' })).toBeDisabled();
  });
});
